ALTER TABLE public.profiles ADD COLUMN telegram_user_id bigint UNIQUE, ADD COLUMN telegram_username text UNIQUE;
CREATE OR REPLACE FUNCTION public.protect_telegram_profile_link() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF current_user <> 'postgres' AND coalesce(auth.role(), '') <> 'service_role' AND (NEW.telegram_user_id IS DISTINCT FROM OLD.telegram_user_id OR NEW.telegram_username IS DISTINCT FROM OLD.telegram_username) THEN RAISE EXCEPTION 'Telegram identity can only be changed by the registration service'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER protect_telegram_profile_link BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_telegram_profile_link();
CREATE TABLE public.telegram_accounts (telegram_user_id bigint PRIMARY KEY, username text NOT NULL UNIQUE, user_id uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.telegram_accounts TO service_role;
ALTER TABLE public.telegram_accounts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.registration_packages (code text PRIMARY KEY, name text NOT NULL, price_usd numeric(12,2) NOT NULL, credits integer NOT NULL DEFAULT 0, duration_days integer NOT NULL DEFAULT 0, enabled boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.registration_packages TO anon, authenticated;
GRANT ALL ON public.registration_packages TO service_role;
ALTER TABLE public.registration_packages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public enabled packages" ON public.registration_packages FOR SELECT TO anon, authenticated USING (enabled);
CREATE TABLE public.website_settings (id boolean PRIMARY KEY DEFAULT true, title text NOT NULL DEFAULT 'AnyDoc — Document Studio', description text NOT NULL DEFAULT 'AnyDoc document studio. Register securely through AnyDocBot.', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.website_settings TO anon, authenticated;
GRANT ALL ON public.website_settings TO service_role;
ALTER TABLE public.website_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public metadata" ON public.website_settings FOR SELECT TO anon, authenticated USING (true);
CREATE TABLE public.registration_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), telegram_user_id bigint NOT NULL REFERENCES public.telegram_accounts(telegram_user_id), package_code text NOT NULL REFERENCES public.registration_packages(code), price_usd numeric(12,2) NOT NULL, credits integer NOT NULL DEFAULT 0, duration_days integer NOT NULL DEFAULT 0, invoice_id bigint UNIQUE, invoice_url text, status text NOT NULL DEFAULT 'pending', processing_until timestamptz, fulfilled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.registration_orders TO service_role;
ALTER TABLE public.registration_orders ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.telegram_update_receipts (update_id bigint PRIMARY KEY, processing_until timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.telegram_update_receipts TO service_role;
ALTER TABLE public.telegram_update_receipts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.account_entitlements (user_id uuid PRIMARY KEY, credits integer NOT NULL DEFAULT 0, expires_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.account_entitlements TO authenticated;
GRANT ALL ON public.account_entitlements TO service_role;
ALTER TABLE public.account_entitlements ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users read own purchases" ON public.account_entitlements FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE OR REPLACE FUNCTION public.complete_registration_order(order_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE o public.registration_orders; u uuid; BEGIN SELECT * INTO o FROM public.registration_orders WHERE id = order_id FOR UPDATE; IF o.id IS NULL OR o.fulfilled_at IS NOT NULL OR o.status <> 'processing' THEN RETURN false; END IF; SELECT user_id INTO u FROM public.telegram_accounts WHERE telegram_user_id = o.telegram_user_id; INSERT INTO public.account_entitlements(user_id, credits, expires_at) VALUES(u, o.credits, CASE WHEN o.duration_days > 0 THEN now() + make_interval(days => o.duration_days) ELSE NULL END) ON CONFLICT (user_id) DO UPDATE SET credits = account_entitlements.credits + o.credits, expires_at = CASE WHEN o.duration_days > 0 THEN greatest(coalesce(account_entitlements.expires_at, now()), now()) + make_interval(days => o.duration_days) ELSE account_entitlements.expires_at END, updated_at = now(); UPDATE public.registration_orders SET status = 'fulfilled', fulfilled_at = now(), processing_until = NULL WHERE id = order_id; RETURN true; END; $$;
REVOKE ALL ON FUNCTION public.complete_registration_order(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.complete_registration_order(uuid) TO service_role;